<div class="repair-fields">@foreach(['name'=>'Name','phone'=>'Phone','email'=>'Email','specialization'=>'Specialization'] as $field=>$label)<x-repair-field :name="$field" :label="$label" :value="$technician?->$field" :type="$field==='email'?'email':'text'" :required="$field==='name'"/>@endforeach<x-repair-field name="status" label="Availability" :value="$technician?->status??'Active'" :options="['Active'=>'Active','Inactive'=>'Inactive','On Leave'=>'On Leave']"/><x-repair-field name="commission_rate" label="Commission %" type="number" step="0.01" min="0" max="100" :value="$technician?->commission_rate??0" required/></div><x-repair-field name="notes" label="Staff notes" type="textarea" :value="$technician?->notes"/><x-repair-field name="photo" label="Technician photo" type="file" accept="image/jpeg,image/png,image/webp"/>
